def transform(grid):
    g = [row[:] for row in grid]
    from collections import Counter

    counts = Counter(v for row in g for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v in counts if v != bg)
    h, w = len(g), len(g[0])

    bands = []
    r = 0
    while r < h:
        if fg not in g[r]:
            r += 1
            continue
        start = r
        while r < h and fg in g[r]:
            r += 1
        bands.append((start, r))
    if len(bands) < 2:
        return g

    (a, b), (c, d) = bands[0], bands[-1]
    n = min(b - a, d - c)

    # In each aligned row pair, extend the pattern with the shorter
    # rightward reach to match the farther-reaching pattern.
    for k in range(n):
        r1, r2 = a + k, c + k
        xs1 = [x for x, v in enumerate(g[r1]) if v == fg]
        xs2 = [x for x, v in enumerate(g[r2]) if v == fg]
        if not xs1 or not xs2:
            continue
        end1, end2 = max(xs1), max(xs2)
        if end1 < end2:
            for x in range(end1 + 1, end2 + 1):
                if g[r1][x] == bg:
                    g[r1][x] = 1
        elif end2 < end1:
            for x in range(end2 + 1, end1 + 1):
                if g[r2][x] == bg:
                    g[r2][x] = 1
    return g
